-- Case 1: Sales Performance 

-- 1 What is the total sales value generated by Olist during the available period?
Select sum(ROUND(price, 0)) as total_sales  from olist_order_items;

-- KPI : Total Product Sales = 13.59M Brazilian Reais

-- 2 How did Olist's sales perform month-by-month across different years?
select Year(oo.order_purchase_timestamp) as year, 
Datename(Month, oo.order_purchase_timestamp) as Month_wise, 
month(oo.order_purchase_timestamp) as month_number, 
SUM(round(oi.price, 0)) as total_sales
from olist_order_items as oi
join olist_orders as oo 
on oi.order_id = oo.order_id
group by Year(oo.order_purchase_timestamp), month(oo.order_purchase_timestamp), Datename(Month, oo.order_purchase_timestamp)
order by year, month_number;

/* KPI: Monthly Sales Trend ✅

Potential insight:
2017 mein sales overall strong upward trajectory dikhati hain, with November as the highest-sales month (~₹10.11 lakh). 2018 ke first several months bhi high sales levels maintain karte hain.
 */

 -- 3 How many orders did Olist receive during the available period?
 select count(distinct(order_id)) as total_order from olist_order_items
 -- KPI	Result
--Total Orders	98,666

-- 4 What is the Average Order Value (AOV) of Olist?
select (sum(price) / count(distinct(order_id)) ) as AOV from olist_order_items;
-- AOV = 137.754076396331

--5 How did Olist's sales grow or decline year-over-year (YoY)?
select year(oo.order_purchase_timestamp) as year , sum(oi.price) as total_sale,
lag(sum(oi.price)) over(order by  year(oo.order_purchase_timestamp))
as Prev_sale,
(sum(oi.price) - lag(sum(oi.price)) over(order by sum(oi.price))) / lag(sum(oi.price)) over(order by sum(oi.price)) * 100
 from olist_orders as oo
 join olist_order_items oi
 on oo.order_id = oi.order_id
 group by year(oo.order_purchase_timestamp);

 --6 Which product categories contributed the most to Olist's total sales?

 select top 10 product_category_name as product_name , sum(round(price,0)) as Top_sale from olist_order_items oi
 join olist_products op 
 on oi.product_id = op.product_id 
 WHERE product_category_name IS NOT NULL
 group by product_category_name
 order by sum(round(price,0)) desc;

 -- 7 What percentage of total sales does each product category contribute? ( Use CTE 2 times )
 -- total sale / category wise indivisual sale * 100

 with Category_Sale as 
 (
select op.product_category_name  , round(sum(price),2) as caty_sale
from olist_order_items oi 
join olist_products op
on oi.product_id = op.product_id 
where op.product_category_name is not null
group by product_category_name 
) , 

Total_sale as
(
select round(sum(price),2) as all_sale from olist_order_items 
)

select product_category_name, caty_sale , all_sale ,  round(caty_sale / all_sale * 100, 2) as percentage_sale
from Category_Sale
cross join Total_sale
order by percentage_sale desc;


-- 8 Olist management wants to understand which customer states generate the highest sales.

select oc.customer_city as state,  round(sum(oi.price),2) as total_sale
from olist_order_items oi
join olist_orders oo
on oi.order_id = oo.order_id
join olist_customers oc
on oc.customer_id = oo.customer_id
group by customer_city
order by total_sale desc ;

-- Finished Sales Performance --
 